// Shared by every script. The document arrives as a JSON string; patches are built up as plain objects.
const S = JSON.parse(state);
const E = S.packages.engine;
const T = E.utilities.time.properties.state;
const DT = Math.min(Math.max(T.delta, 0.001), 0.05);
const patch = {};
const X = {};   // what one section of the frame tells a later one, without going through the document
const node = path => {
	let n = patch;
	for (const k of path.split('.')) { n.packages = n.packages || {}; n = n.packages[k] = n.packages[k] || {}; }
	return n;
};
const put = (path, data) => {
	const n = node(path);
	n.properties = n.properties || {}; n.properties.meta = n.properties.meta || {};
	n.properties.meta.data = Object.assign(n.properties.meta.data || {}, data);
};
const comp = (path, name, data, content) => {
	const n = node(path);
	n.utilities = n.utilities || {};
	const u = n.utilities[name] = n.utilities[name] || {};
	if (data) { u.properties = u.properties || {}; u.properties.data = Object.assign(u.properties.data || {}, data); }
	if (content !== undefined) u.content = content;
};
const get = path => {
	let n = S;
	for (const k of path.split('.')) { n = n.packages && n.packages[k]; if (!n) return null; }
	return n;
};
const dat = path => { const n = get(path); return n && n.properties && n.properties.meta ? n.properties.meta.data : null; };
const done = () => Object.keys(patch).length ? JSON.stringify(patch) : undefined;

const len = v => Math.hypot(v[0], v[1], v[2]);
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = a => { const l = len(a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const wrap = a => { while (a > Math.PI) a -= 2 * Math.PI; while (a < -Math.PI) a += 2 * Math.PI; return a; };
const heading = (yaw, pitch) => [-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch)];
const hash = x => { const s = Math.sin(x * 12.9898 + 78.233) * 43758.5453; return s - Math.floor(s); };

// Applies a patch to this script's own copy of the document, so that a later section of the same script sees
// what an earlier one decided, exactly as a separate script would have, without a round trip through the engine.
const mergeInto = (target, patchObject) => {
	for (const k of Object.keys(patchObject)) {
		const v = patchObject[k];
		if (v === null) delete target[k];
		else if (v && typeof v === 'object' && !Array.isArray(v) && target[k] && typeof target[k] === 'object' && !Array.isArray(target[k])) mergeInto(target[k], v);
		else target[k] = (v && typeof v === 'object') ? JSON.parse(JSON.stringify(v)) : v;
	}
};

const NAMES = {"constellations":["Andromedae","Antliae","Apodis","Aquarii","Aquilae","Arae","Archimediae","Arietis","Arii","Aurigae","Azophi","Barnard","Berenices","Boötis","Botes","Caeli","Cameliae","Camelopardalis","Cancri","Canesis","Cannonis","Canis","Carteri","Capricorni","Carinae","Cassini","Cassiopeiae","Centauri","Cephei","Ceti","Chamaeleontis","Circini","Columbae","Comae","Conway","Copernici","Coronae","Corvi","Crateris","Crucis","Curi","Cygni","Darwini","Delphini","Da Vinci","Delphini","Descartes","Dijkstrae","Doradus","Draconis","Drakes","Eich","Einsteini","Equulei","Eratosthenis","Eridani","Euclidae","Euleris","Europae","Fornacis","Gaussi","Galilei","Geminorum","Gruis","Hamiltoni","Hawking","Herculis","Herschel","Hopperae","Horologii","Hubblis","Huygentis","Hyades","Hydrae","Hydri","Hypatiae","Indi","Kapteyni","Kepleris","Lacertae","Leavitis","Leonis","Leporis","Librae","Lovelace","Lupi","Lyncis","Lyrae","Mensae","Messier","Microscopii","Mobii","Monocerotis","Muscae","Neumanni","Newtonis","Normae","Octantis","Ophiuchi","Orionis","Pavonis","Pegasi","Persei","Phoenicis","Pictoris","Piscium","Piscis","Ptolemæi","Puppis","Pythagorae","Pyxidis","Reticuli","Saganis","Sagittae","Sagittarii","Scorpii","Sculptoris","Scuti","Serpentis","Sextantis","Tauri","Telescopii","Torvaldi","Trianguli","Tucanae","Turingi","Ursae","Velorum","Virginis","Volantis","Vulpeculae","Weierstrass","Zeno","Zimmerman"],"greek":["Alpha","Beta","Gamma","Delta","Epsilon","Zeta","Eta","Theta","Iota","Kappa","Lambda","Mu","Nu","Xi","Omicron","Pi","Rho","Sigma","Tau","Upsilon","Phi","Chi","Psi","Omega"]};
// The universe, as a function. A port of Cosmos Journeyer's procedural generation (packages/random, physics, universe-model and universe-generation,
// by Barthélemy Paléologue, AGPL-3.0): the same seeded generators and the same distributions, so a system is a pure function of its coordinates.
// Nothing here knows about a scene. (Names come from NAMES, put in front of this by the build.)
const U = (() => {
	const PI = Math.PI;
	const C = 299792458, G = 6.6743e-11;
	const EarthMass = 5.972e24, EarthSeaLevelPressure = 101325, JupiterMass = 1.898e27, JupiterRadius = 69911e3;
	const SolarMass = 1.989e30, SolarRadius = 696340e3, MoonMass = 7.348e22, AU = 1.495978707e11;
	const ScaledEarthRadius = 1000e3, CloudLayerHeight = 7e3, SeedHalfRange = 1e4;
	const UNIVERSE_SEED = PI, STAR_SECTOR_SIZE = 20, LIGHT_YEAR = C * 60 * 60 * 24 * 365.25;
	const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
	const lerp = (a, b, t) => a + (b - a) * t;
	const degrees = d => d * PI / 180;

	// ---- random (packages/random): the legacy squirrel noise, kept as it is so that the same coordinates give the same worlds
	const legacy = (seed, index) => {
		let m = index;
		m *= 0x68e31da4; m += seed; m ^= m >> 8; m += 0xb5297a4d; m ^= m << 8; m *= 0x1b56c4e9; m ^= m >> 8;
		return m / (2 ** 31 - 1);
	};
	const rngFromSeed = seed => index => legacy(seed, index);
	const centeredRand = (rng, step) => (rng(step) - 0.5) * 2;
	const randRangeInt = (min, max, rng, step) => Math.floor(rng(step) * (max - min + 1)) + min;
	const randRange = (min, max, rng, step) => rng(step) * (max - min) + min;
	const normalRandom = (mean, std, rng, step) => mean + std * Math.sqrt(-2 * Math.log(rng(step))) * Math.cos(2 * PI * rng(step + 1));
	const uniformRandBool = (p, rng, step) => rng(step) < p;
	const wheelOfFortune = (options, value) => {
		const total = options.reduce((a, o) => a + o[1], 0), choice = value * total;
		let current = 0;
		for (const [option, weight] of options) { current += weight; if (choice < current) return option; }
		throw new Error("Wheel of fortune failed");
	};
	const hashVec3 = (x, y, z) => ((x * 73856093) ^ (y * 19349663) ^ (z * 83492791)) % 1000000000;

	// ---- physics (packages/physics)
	const celsiusToKelvin = c => c + 273.15;
	const getTemperatureLine = (T, R, target) => 0.5 * R * (T / target) ** 2;
	const getSilicateRockSublimationLine = (T, R) => getTemperatureLine(T, R, 1500);
	const getWaterIceFrostLine = (T, R) => getTemperatureLine(T, R, 170);
	const computeEffectiveTemperature = (stars, albedo) => {
		let flux = 0;
		for (const s of stars) flux += (s.temperature ** 4 * s.radius ** 2) / s.distance ** 2;
		return Math.pow(((1 - albedo) * flux) / 4, 0.25);
	};
	const waterBoilingTemperature = pressure => {
		const P1 = 101325, T1 = celsiusToKelvin(100), DH = 40660, R = 8.314;
		if (pressure <= 0) return 0;
		return 1 / (1 / T1 + Math.log(P1 / pressure) * (R / DH));
	};
	const hasLiquidWater = (pressure, tMin, tMax) => {
		const boil = waterBoilingTemperature(pressure), freeze = celsiusToKelvin(0);
		if (pressure < 0.05) return false;
		if (boil < freeze) return false;
		if (tMin > boil) return false;
		if (tMax < freeze) return false;
		return true;
	};
	const getWaterSaturationPressure = T => 37960000000 * Math.exp(-2260000 / (461.5 * T));
	const getOceanDepth = (R, mass, ratio, coverage) => Math.cbrt(R ** 3 + (3 * (ratio * mass / 1000)) / (4 * PI * coverage)) - R;
	const getTemperatureRange = (effective, greenhouse, pressure) => {
		const redistribution = clamp(pressure / (2 * EarthSeaLevelPressure), 0, 1);
		const mean = effective + greenhouse;
		const span = lerp(60, 15, redistribution);
		return { min: mean - 0.65 * span, max: mean + 0.35 * span };
	};
	const getCoolGasGiantRadiusFromMass = mass => {
		const x = Math.log10(mass / JupiterMass);
		return (0.96 + 0.21 * x - 0.2 * x * x) * JupiterRadius;
	};
	const getOrbitalPeriod = (a, M) => (M === 0 ? 0 : 2 * PI * Math.sqrt(a ** 3 / (G * M)));
	const getSchwarzschildRadius = mass => (2 * G * mass) / C ** 2;

	// ---- colours
	const hsvToRgb = (h, s, v) => {
		const hue = ((h % 360) + 360) % 360, c = v * s, x = c * (1 - Math.abs(((hue / 60) % 2) - 1)), m = v - c;
		let r, g, b;
		if (hue < 60) { r = c; g = x; b = 0; } else if (hue < 120) { r = x; g = c; b = 0; } else if (hue < 180) { r = 0; g = c; b = x; }
		else if (hue < 240) { r = 0; g = x; b = c; } else if (hue < 300) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
		return [r + m, g + m, b + m];
	};

	const romanNumeral = n => {
		const table = [[1000, "M"], [900, "CM"], [500, "D"], [400, "CD"], [100, "C"], [90, "XC"], [50, "L"], [40, "XL"], [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"]];
		let out = "";
		for (const [v, s] of table) while (n >= v) { out += s; n -= v; }
		return out;
	};
	const Alphabet = "abcdefghijklmnopqrstuvwxyz", ReversedGreek = "ωψχφυτσρποξνμλκιθηζεδγβα";
	const starName = (rng, base) => NAMES.greek[Math.floor(rng(base + 1) * NAMES.greek.length)] + " " + NAMES.constellations[Math.floor(rng(base) * NAMES.constellations.length)];

	const STEP = { AXIAL_TILT: 100, ORBIT: 200, RADIUS: 1000, RINGS: 1200, TEMPERATURE: 1100, STELLAR_TYPE: 1900, PRESSURE: 1800, WATER_AMOUNT: 1700, TERRAIN: 1500, MAGNETIC_FIELD: 2600, SIDEREAL: 2500 };

	const id = (parents, type, index) => `[${parents.join("|")}]->${type}${index}`;

	// ---- rings
	const generateRings = (radius, rng) => {
		const inner = radius * randRange(1.8, 2.2, rng, 1400);
		const width = radius * Math.max(0.2, normalRandom(1.0, 0.5, rng, 1405));
		const b = randRange(0.35, 0.65, rng, 1430), w = randRange(0, 1, rng, 1431);
		const dr = randRange(-0.03, 0.04, rng, 1432), dg = randRange(-0.02, 0.03, rng, 1433), db = randRange(-0.03, 0.02, rng, 1434);
		return {
			innerRadius: inner, outerRadius: inner + width, seed: randRange(-1, 1, rng, 1440), frequency: 10,
			ice: [0.93, 0.92, 0.9], dust: [b * (0.86 + 0.1 * w + dr), b * (0.78 + 0.08 * w + dg), b * (0.68 - 0.08 * w + db)]
		};
	};

	// ---- clouds
	const generateClouds = (planetRadius, coverageOcean, averageT, pressure) => {
		const saturation = getWaterSaturationPressure(averageT);
		const coverage = 0.8 * (1 - Math.exp((-30 * coverageOcean * saturation) / pressure));
		return { height: CloudLayerHeight, coverage, frequency: 4 };
	};

	// ---- stars
	const stellarType = rng => wheelOfFortune([["M", 0.765], ["K", 0.121], ["G", 0.076], ["F", 0.03], ["A", 0.006], ["B", 0.0013], ["O", 0.0000003]], rng(STEP.STELLAR_TYPE));
	const TEMPERATURE = { M: [2100, 3400], K: [3400, 4900], G: [4900, 5700], F: [5700, 7200], A: [7200, 9700], B: [9700, 30000], O: [30000, 52000] };
	const RADIUS = { M: [0.5, 0.7], K: [0.7, 0.9], G: [0.9, 1.1], F: [1.1, 1.4], A: [1.4, 1.8], B: [1.8, 6.6], O: [6.6, 15] };

	const generateStar = (oid, seed, name) => {
		const rng = rngFromSeed(seed);
		const type = stellarType(rng);
		const temperature = randRangeInt(TEMPERATURE[type][0], TEMPERATURE[type][1], rng, STEP.TEMPERATURE);
		const radius = randRange(RADIUS[type][0], RADIUS[type][1], rng, STEP.RADIUS) * SolarRadius;
		const rings = uniformRandBool(0.2, rng, STEP.RINGS) ? generateRings(radius, rng) : null;
		return { type: "star", id: oid, name, seed, radius, temperature, mass: 1.9885e30, spectral: type, spin: { period: 24 * 3600, tilt: 0 }, orbit: { parents: [], a: 0, inclination: 0, phase: 0 }, rings };
	};

	const generateBlackHole = (oid, seed, name) => {
		const rng = rngFromSeed(seed);
		const rs = 1000e3;
		return {
			type: "blackHole", id: oid, name, seed, radius: rs, mass: rs * C ** 2 / (2 * G), temperature: 7000, spectral: "BH",
			spin: { period: 1.5e-19, tilt: normalRandom(0, 0.4, rng, STEP.AXIAL_TILT) }, diskRadius: rs * normalRandom(12, 3, rng, 7777),
			orbit: { parents: [], a: 0, inclination: 0, phase: 0 }, rings: null
		};
	};

	const generateNeutronStar = (oid, seed, name) => {
		const rng = rngFromSeed(seed);
		const radius = clamp(normalRandom(10e3, 1e3, rng, STEP.RADIUS), 2e3, 50e3);
		return {
			type: "neutronStar", id: oid, name, seed, radius, mass: 1.9885e30, temperature: randRangeInt(200000, 5000000, rng, STEP.TEMPERATURE), spectral: "NS",
			spin: { period: clamp(normalRandom(0.5e-2, 5e-3, rng, STEP.SIDEREAL), 1.4e-3, 30), tilt: 0 },
			orbit: { parents: [], a: 0, inclination: 0, phase: 0 }, rings: uniformRandBool(0.02, rng, STEP.RINGS) ? generateRings(radius, rng) : null
		};
	};

	// ---- planets
	const getTelluricPlanetOrbitRadius = (T, R, rng) => {
		const lower = getSilicateRockSublimationLine(T, R), upper = getWaterIceFrostLine(T, R);
		return lower * Math.exp(Math.log(upper / lower) * rng());
	};

	const getGasPlanetOrbitRadius = (T, R, rng) => {
		const snow = getWaterIceFrostLine(T, R);
		if (rng(2564) < 0.01) {
			const aMin = Math.max(10 * R, 0.02 * AU), aMax = Math.min(0.1 * AU, snow * 0.5), upper = Math.max(aMax, aMin * 1.5);
			return aMin * Math.exp(Math.log(upper / aMin) * rng(865));
		}
		const aMin = Math.max(snow * 1.3, 10 * R);
		let aMax = snow * 3;
		if (aMax <= aMin) aMax = aMin * 1.5;
		const sMin = Math.sqrt(aMin), sMax = Math.sqrt(aMax), sA = sMin + (sMax - sMin) * rng(865);
		return sA * sA;
	};

	const sampleGasPlanetMass = rng => {
		const lo = Math.log10(0.08 * JupiterMass), hi = Math.log10(8 * JupiterMass);
		return 10 ** (lo + (hi - lo) * rng(3421));
	};

	const generateTelluricPlanet = (oid, seed, name, parents) => {
		const rng = rngFromSeed(seed);
		const radius = Math.max(0.1, normalRandom(1.0, 0.4, rng, STEP.RADIUS)) * ScaledEarthRadius;
		const mass = EarthMass * (radius / 6371e3) ** 3;
		const orbitRadii = [];
		for (const p of parents) orbitRadii.push(getTelluricPlanetOrbitRadius(p.temperature, p.radius, () => rng(STEP.ORBIT + orbitRadii.length)));
		const a = parents.length > 0 ? Math.max(...orbitRadii) : 0;
		let avgIncl = 0, avgTilt = 0;
		for (const p of parents) { avgIncl += p.orbit.inclination; avgTilt += p.spin.tilt; }
		avgIncl /= parents.length; avgTilt /= parents.length;
		const orbit = { parents: parents.map(p => p.id), a, inclination: avgIncl + avgTilt + degrees(normalRandom(0, 5, rng, STEP.ORBIT + 10)), phase: 0 };
		let pressure = Math.max(normalRandom(0.8, 0.4, rng, STEP.PRESSURE) * EarthSeaLevelPressure, 0);
		if (radius <= 0.3 * ScaledEarthRadius) pressure = 0;
		const atmosphere = pressure > 0 ? { pressure } : null;
		const effective = computeEffectiveTemperature(parents.map(p => ({ temperature: p.temperature, radius: p.radius, distance: orbit.a })), 0.3);
		const range = getTemperatureRange(effective, 40, pressure);
		const spin = { period: (60 * 60 * 24) / 10, tilt: normalRandom(0, 0.2, rng, STEP.AXIAL_TILT) };
		const waterAmount = clamp(normalRandom(0.02, 0.01, rng, STEP.WATER_AMOUNT), 0, 0.2);
		const liquid = hasLiquidWater(pressure, range.min, range.max);
		let oceanCoverage = clamp(normalRandom(0.8, 0.1, rng, STEP.TERRAIN), 0.1, 0.95);
		if (pressure === 0) oceanCoverage = 0;
		const ocean = liquid ? { depth: getOceanDepth(radius, mass, waterAmount, oceanCoverage) } : null;
		if (ocean === null) oceanCoverage /= 1.3;
		const averageT = (range.min + range.max) / 2;
		const clouds = ocean !== null ? generateClouds(radius + ocean.depth, oceanCoverage, averageT, pressure) : null;
		const terrain = {
			continentsFrequency: radius / ScaledEarthRadius, continentsFragmentation: oceanCoverage, bumpsFrequency: (30 * radius) / ScaledEarthRadius,
			maxBumpHeight: 1.5e3, maxMountainHeight: 10e3, continentBaseHeight: ocean !== null ? ocean.depth : 0, mountainsFrequency: (60 * radius) / ScaledEarthRadius
		};
		const rings = uniformRandBool(0.01, rng, STEP.RINGS) ? generateRings(radius, rng) : null;
		return { type: "telluricPlanet", id: oid, seed, name, mass, radius, spin, orbit, temperature: range, atmosphere, ocean, clouds, terrain, rings };
	};

	const generateGasPlanet = (oid, seed, name, parents) => {
		const rng = rngFromSeed(seed);
		const mass = sampleGasPlanetMass(rng);
		const radius = getCoolGasGiantRadiusFromMass(mass);
		const orbitRadii = [];
		for (const p of parents) orbitRadii.push(getGasPlanetOrbitRadius(p.temperature, p.radius, rng));
		const a = parents.length > 0 ? Math.max(...orbitRadii) : 0;
		let avgIncl = 0, avgTilt = 0;
		if (parents.length > 0) { for (const p of parents) { avgIncl += p.orbit.inclination; avgTilt += p.spin.tilt; } avgIncl /= parents.length; avgTilt /= parents.length; }
		const orbit = { parents: parents.map(p => p.id), a, inclination: avgIncl + avgTilt + degrees(normalRandom(0, 5, rng, STEP.ORBIT + 10)), phase: 0 };
		const spin = { period: (24 * 60 * 60) / 10, tilt: normalRandom(0, degrees(25), rng, STEP.AXIAL_TILT) };
		const rings = uniformRandBool(0.8, rng, STEP.RINGS) ? generateRings(radius, rng) : null;
		const hue1 = normalRandom(240, 30, rng, 70), hue2 = normalRandom(0, 180, rng, 72);
		const c1 = hsvToRgb(hue1 % 360, randRange(0.4, 0.9, rng, 72), randRange(0.7, 0.9, rng, 73));
		const c2 = hsvToRgb(hue2 % 360, randRange(0.6, 0.9, rng, 74), randRange(0, 0.3, rng, 75));
		const c3 = hsvToRgb((hue1 - 180) % 360, randRange(0.4, 0.9, rng, 76), randRange(0.7, 0.9, rng, 77));
		const sharpness = randRangeInt(40, 80, rng, 80) / 10;
		return { type: "gasPlanet", id: oid, seed, name, mass, radius, spin, orbit, atmosphere: { pressure: EarthSeaLevelPressure }, rings, palette: { color1: c1, color2: c2, color3: c3, sharpness } };
	};

	const generateSatellite = (oid, seed, name, parents, stars) => {
		const rng = rngFromSeed(seed);
		const ofTelluric = parents.some(p => p.type === "telluricPlanet"), ofGas = parents.some(p => p.type === "gasPlanet");
		let radius;
		if (ofTelluric) radius = Math.max(0.03, normalRandom(0.06, 0.03, rng, STEP.RADIUS)) * ScaledEarthRadius;
		else if (ofGas) radius = Math.max(0.03, normalRandom(0.25, 0.15, rng, STEP.RADIUS)) * ScaledEarthRadius;
		else throw new Error("Satellite is not around telluric or gas planet");
		const mass = ofTelluric ? MoonMass * (radius / 1735e3) ** 3 : EarthMass * (radius / 6371e3) ** 3;
		let pressure = Math.max(normalRandom(EarthSeaLevelPressure, 0.2 * EarthSeaLevelPressure, rng, STEP.PRESSURE), 0);
		if (ofTelluric || radius <= 0.3 * ScaledEarthRadius) pressure = 0;
		const stellar = [];
		for (const s of stars) {
			let avg = 0, count = 0;
			for (const p of parents) if (p.orbit.parents.includes(s.id)) { avg += p.orbit.a; count++; }
			if (count > 0) stellar.push({ s, distance: avg / count });
		}
		const effective = computeEffectiveTemperature(stellar.map(o => ({ temperature: o.s.temperature, radius: o.s.radius, distance: o.distance })), 0.3);
		const range = getTemperatureRange(effective, 40, pressure);
		const waterAmount = clamp(normalRandom(0.5, 0.1, rng, STEP.WATER_AMOUNT), 0, 1);
		const atmosphere = pressure > 0 ? { pressure } : null;
		const liquid = hasLiquidWater(pressure, range.min, range.max);
		let oceanCoverage = clamp(normalRandom(0.8, 0.1, rng, STEP.TERRAIN), 0.1, 0.95);
		if (pressure === 0) oceanCoverage = 0;
		const ocean = liquid ? { depth: getOceanDepth(radius, mass, waterAmount, oceanCoverage) } : null;
		if (ocean === null) oceanCoverage /= 1.3;
		const parentMax = parents.reduce((m, p) => Math.max(m, p.radius), 0);
		let a = parentMax * clamp(normalRandom(2, 0.3, rng, STEP.ORBIT), 1.2, 3);
		a += parentMax * clamp(normalRandom(10, 4, rng, STEP.ORBIT), 1, 50);
		a += 2 * parentMax;
		const parentMass = parents.reduce((s, p) => s + p.mass, 0);
		let avgIncl = 0, avgTilt = 0;
		for (const p of parents) { avgIncl += p.orbit.inclination; avgTilt += p.spin.tilt; }
		avgIncl /= parents.length; avgTilt /= parents.length;
		const orbit = { parents: parents.map(p => p.id), a, inclination: avgIncl + avgTilt + degrees(normalRandom(0, 5, rng, STEP.ORBIT + 10)), phase: 0 };
		const spin = { period: getOrbitalPeriod(a, parentMass), tilt: 0 };
		const averageT = (range.min + range.max) / 2;
