// ---- ship.js
{
// The ship. Flown with the mouse and a throttle, in the frame of the nearest world: within two radii and a half the frame turns with the world (so a ship at rest
// on the ground stays there), farther out it only travels with it, and at the edge of the system it is the star's. Speed is limited by how far there is to the
// nearest surface, so that the way in from orbit to the ground is one smooth fall in speed; the warp drive lifts the limit outside the atmosphere.
const G = dat('game'), SH = dat('ship');
const kb = E.packages.controllers.utilities['keyboard-0'], pt = E.packages.controllers.utilities['pointer-0'];
const keys = kb ? kb.properties.state.digital : [], struck = kb ? kb.properties.state.pressed : [];
const on = k => keys.indexOf(k) >= 0, hit = k => struck.indexOf(k) >= 0;
const disp = E.utilities.display.properties.state;
const dt = Math.min(Math.max(DT, 0.001), 0.05);
const mode = G.mode;
let P = SH.position.slice(), V = SH.vel.slice(), Q = SH.rotation.slice(), speed = SH.speed || 0, throttle = SH.throttle || 0, warp = SH.warp || 0;
const bodies = X.bodies;
const now = b => X.pos[b.id].p, prev = b => X.posPrev[b.id].p;
const planetLike = b => b.type === 'telluricPlanet' || b.type === 'telluricSatellite' || b.type === 'gasPlanet';
const sea = b => (b.ocean ? b.ocean.depth : 0);

// ---- placed at the start of a system: in sight of a world, on the side the star lights
if (X.fresh) {
	const pick = bodies.find(b => b.type === 'telluricPlanet' && b.ocean && b.atmosphere) || bodies.find(b => b.type === 'telluricPlanet' && b.atmosphere) || bodies.find(planetLike) || bodies[0];
	const c = now(pick), s = now(bodies[0]);
	const toStar = pick === bodies[0] ? [0, 0, 1] : vnorm(vsub(s, c));
	const side = vnorm(vcross(toStar, [0, 1, 0]));
	const dir = vnorm(vadd(vscale(toStar, 0.86), vscale(side, 0.5)));
	const distance = pick.radius * (pick === bodies[0] ? 14 : 4.2) + (pick === bodies[0] ? 0 : sea(pick));
	P = vadd(c, vscale(dir, distance));
	Q = qlook(vscale(dir, -1), [0, 1, 0]);
	V = [0, 0, 0]; speed = 0; throttle = 0; warp = 0;
	put('ship', { frame: pick.id, fmode: 'inertial' });
}

// ---- the controls
if (G.mode === 'title') {
	if (hit('Enter') || hit('Space') || (pt && pt.properties.state.pressed.indexOf('button0') >= 0)) put('game', { mode: 'fly' });
	speed = 0;
} else if (mode === 'fly') {
	const a = pt ? pt.properties.state.analog : {};
	let yaw = disp.locked ? -(a.dx || 0) * 3.2 : 0, pitch = disp.locked ? (a.dy || 0) * 3.2 : 0;
	yaw += ((on('ArrowLeft') ? 1 : 0) - (on('ArrowRight') ? 1 : 0)) * 1.1 * dt;
	pitch += ((on('ArrowUp') ? 1 : 0) - (on('ArrowDown') ? 1 : 0)) * 1.1 * dt;
	const roll = ((on('KeyQ') ? 1 : 0) - (on('KeyE') ? 1 : 0)) * 1.5 * dt + ((on('KeyA') ? 1 : 0) - (on('KeyD') ? 1 : 0)) * 0.8 * dt;
	Q = qnorm(qmul(Q, qmul(qaxis([0, 1, 0], yaw), qmul(qaxis([1, 0, 0], pitch), qaxis([0, 0, 1], roll)))));
	if (on('KeyW')) throttle = Math.min(1, throttle + 0.6 * dt);
	if (on('KeyS')) throttle = Math.max(0, throttle - 0.9 * dt);
	if (on('ControlLeft')) throttle = Math.max(0, throttle - 3 * dt);
	if (hit('KeyX')) throttle = 0;
	if (hit('Space')) warp = warp ? 0 : 1;
}

// ---- how fast it may go: by the distance to the nearest surface
let nearest = null, nearestD = Infinity, nearestIndex = 0;
bodies.forEach((b, i) => {
	const d = vlen(vsub(P, now(b))) - b.radius - (planetLike(b) ? sea(b) : 0);
	if (d < nearestD) { nearestD = d; nearest = b; nearestIndex = i; }
});
const dn = Math.max(nearestD, 1), nearR = nearest.radius;
const cruiseMax = clamp(dn * 0.5, 40, 3e5);
const warpMax = dn > 2 * nearR + 3e5 ? clamp(dn * 2, 2e4, 3e10) : 0;
if (warp && warpMax < cruiseMax * 1.5) warp = 0;
let vmax = warp ? warpMax : cruiseMax;
if (!warp && mode === 'fly' && on('ShiftLeft')) vmax *= 3;
const target = mode === 'fly' || mode === 'map' ? throttle * vmax : 0;
speed += (target - speed) * (1 - Math.exp(-(target > speed ? (warp ? 1.4 : 0.9) : 3) * dt));
if (speed < 0.01) speed = 0;
const forward = qrot(Q, [0, 0, -1]);
V = vscale(forward, speed);

// ---- the frame: the nearest world's, if close, and the star's otherwise
let frame = bodies[0], best = Infinity;
const current = SH.frame ? bodies.find(b => b.id === SH.frame) : null;
bodies.forEach(b => {
	const score = (vlen(vsub(P, now(b))) - b.radius) / b.radius;
	if (score < best && (b === bodies[0] || score < 6)) { best = score; frame = b; }
});
if (current && current !== frame) {
	const cs = (vlen(vsub(P, now(current))) - current.radius) / current.radius;
	if (cs < best * 1.35 && (current === bodies[0] || cs < 6)) frame = current;
}
const rotating = frame !== bodies[0] && planetLike(frame) && (vlen(vsub(P, now(frame))) - frame.radius) < 2.5 * frame.radius;
const dprev = Math.max(DT, 1e-3);
const qnow = b => spinQuat(spinOf(b, G.t0), T.elapsed), qprev = b => spinQuat(spinOf(b, G.t0), T.elapsed - dprev);
let moved = [0, 0, 0], turned = null;
if (frame !== bodies[0]) {
	const c0 = prev(frame), c1 = now(frame);
	if (rotating) {
		turned = qnorm(qmul(qnow(frame), qconj(qprev(frame))));
		moved = vsub(vadd(c1, qrot(turned, vsub(P, c0))), P);
	} else moved = vsub(c1, c0);
}
P = vadd(vadd(P, moved), vscale(V, dt));
if (turned) Q = qnorm(qmul(turned, Q));

// ---- the ground, and the surfaces of everything else
const clearance = 6;
const stateOf = (b, i) => { const n = get('systems.' + X.root + '.b' + i); return n && n.utilities && n.utilities.planet ? n.utilities.planet.properties.state : null; };
let altitude = null;
bodies.forEach((b, i) => {
	const c = now(b), rel = vsub(P, c), d = vlen(rel);
	let push = null, alt;
	if (b.type === 'telluricPlanet' || b.type === 'telluricSatellite') {
		const st = stateOf(b, i);
		if (st && st.altitude != null && st.up) {
			alt = st.altitude;
			const upWorld = qrot(qnow(b), st.up);
			if (alt < clearance) push = [upWorld, clearance - alt];
		} else if (d < b.radius * 1.02) push = [vnorm(rel), b.radius * 1.02 - d];
	} else {
		alt = d - b.radius;
		if (alt < clearance + b.radius * 0.02) push = [vnorm(rel), clearance + b.radius * 0.02 - alt];
	}
	if (b === nearest) altitude = alt != null ? alt : d - b.radius;
	if (push) {
		P = vadd(P, vscale(push[0], push[1]));
		const into = vdot(V, push[0]);
		if (into < 0) { V = vsub(V, vscale(push[0], into)); speed = vlen(V); }
	}
});

put('ship', {
	position: [P[0], P[1], P[2]], rotation: Q, vel: V, speed, throttle, warp, frame: frame.id, fmode: rotating ? 'rotating' : 'inertial',
	nearest: nearest.id, nearestIndex, nearestName: nearest.name, nearestType: nearest.type, distance: nearestD, altitude: altitude != null ? altitude : nearestD, warpMax, cruiseMax
});

// ---- the pointer: held in flight, free otherwise
const wantCursor = mode === 'fly' ? 'locked' : 'free';
const curDisplay = E.utilities.display.properties.data || {};
if (curDisplay.cursor !== wantCursor) node('engine').utilities = { display: { properties: { data: { cursor: wantCursor } } } };
if (X.fresh) put('game', { fresh: 0 });

}
